pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Since N <= 0x3FFF_FFFF fits in usize for indexing safely,
    // convert N to usize for index operations.
    let n = N as usize;

    // It's assumed that a.len() == b.len() == N.
    // We'll iterate over all indices 0..N
    let mut sum = 0;

    for i in 0..n {
        // i as i32 for comparison with elements in b
        let idx = i as i32;
        let val = b[i];

        // According to problem: val == i or val == i + 1
        // So assign accordingly:
        let new_val = if val == idx { 1 } else { 2 };

        a[i] = new_val;
        sum += new_val;
    }

    sum
}